/**
 * The sidebar of DashboardShell. Shapes: wide (icon and name), rail (icons only, the names still read),
 * collapsed (the static collapsed state of a wide sidebar, with its expand button), twolevel (a rail beside a
 * panel of the current section's links). side puts it at the start or the end.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { ButtonPlain } from "../primitives/button-plain/button-plain";
import { Group } from "../primitives/group/group";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Text } from "../primitives/text/text";
import { NavBlock } from "../components/nav-block";
import { cn, tpl, uniqLabel } from "../utils";
import type { ShellNav } from "../blocks/dashboard-shell.types";

export type ShellSidebarProps = {
  nav: ShellNav;
  mode?: "wide" | "rail" | "collapsed" | "twolevel" | "none";
  side?: "start" | "end";
  brand?: "show" | "hide";
  landmarkLabel?: string;
  onToggle?: () => void;
};

export function ShellSidebar({
  nav,
  mode = "wide",
  side = "start",
  brand = "show",
  landmarkLabel,
  onToggle,
}: ShellSidebarProps) {
  const named = (mode as string) === "wide";
  return (
    <Block
      tag="aside"
      className={cn(
        "flex shrink-0 bg-card",
        (
          (side as string) === "end" ? "flex-row-reverse border-l border-border"
          : "border-r border-border"
        )
      )}
      aria-label={(landmarkLabel ?? nav.label)}
      data-testid="sidebar"
      data-mode={mode}
    >
      <Box className={cn("flex flex-col gap-6 py-4", (named ? "w-64 px-4" : "w-16 items-center px-2"))}>
        {((brand as string) === "show") ? (
          <Group gap="2" align="center" className="shrink-0" data-testid="brand">
            <LucideIcon name="layers" size={24} />
            <Text size="base" weight="bold" className={(named ? "" : "sr-only")}>
              {nav.brand}
            </Text>
          </Group>
        ) : null}
        <NavBlock
          label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", nav.label, landmarkLabel)) : nav.label)}
          className="flex-1"
        >
          <List className="m-0 flex list-none flex-col gap-2 p-0" data-testid="items">
            {(nav.links ?? []).map((l) => (
              <ListItem key={l.id}>
                <Link
                  href="#/"
                  variant="default"
                  size="sm"
                  aria-current={((l.id === nav.current) ? "page" : undefined)}
                  className={cn(
                    "flex items-center gap-4 rounded py-2",
                    (named ? "px-4" : "justify-center px-2"),
                    ((l.id === nav.current) ? "bg-muted font-medium" : "")
                  )}
                  data-testid="item"
                >
                  <LucideIcon name={l.icon} size={16} />
                  <Inline className={(named ? "" : "sr-only")}>
                    {l.name}
                  </Inline>
                </Link>
              </ListItem>
            ))}
          </List>
        </NavBlock>
        {((mode as string) === "collapsed") ? (
          <ButtonPlain
            type="button"
            className="inline-flex size-10 items-center justify-center rounded text-muted-foreground"
            aria-label={nav.expand}
            aria-expanded={(((mode as string) === "wide") ? "true" : "false")}
            data-testid="toggle"
            onClick={() => onToggle?.()}
          >
            <LucideIcon name="panel-left" size={20} />
          </ButtonPlain>
        ) : null}
      </Box>
      {((mode as string) === "twolevel") ? (
        <Box
          className={cn(
            "flex w-56 flex-col gap-4 px-4 py-6",
            (((side as string) === "end") ? "border-r border-border" : "border-l border-border")
          )}
          data-testid="subnav"
        >
          <Text size="sm" weight="semibold" className="px-4">
            {nav.subTitle}
          </Text>
          <NavBlock label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", nav.subTitle, landmarkLabel)) : nav.subTitle)}>
            <List className="m-0 flex list-none flex-col gap-2 p-0">
              {(nav.sub ?? []).map((s) => (
                <ListItem key={s.id}>
                  <Link
                    href="#/"
                    variant="default"
                    size="sm"
                    aria-current={((s.id === nav.subCurrent) ? "page" : undefined)}
                    className={cn(
                      "flex items-center gap-4 rounded py-2",
                      (true ? "px-4" : "justify-center px-2"),
                      ((s.id === nav.subCurrent) ? "bg-muted font-medium" : "")
                    )}
                    data-testid="item"
                  >
                    <LucideIcon name={s.icon} size={16} />
                    <Inline className={(true ? "" : "sr-only")}>
                      {s.name}
                    </Inline>
                  </Link>
                </ListItem>
              ))}
            </List>
          </NavBlock>
        </Box>
      ) : null}
    </Block>
  );
}
